"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Avatar Group: generated by UIX from the design system. Same variants and sizes as the Figma component.

const avatarGroupVariants = cva(
  "skin-quiet flex items-center",
  {
    variants: {
      size: {
        sm: "-space-x-[6px] text-label-small [&>*]:ring-2 [&>*]:ring-surface",
        md: "-space-x-[8px] text-label-small [&>*]:ring-2 [&>*]:ring-surface",
        lg: "-space-x-[10px] text-label-medium [&>*]:ring-2 [&>*]:ring-surface",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

// Avatar size and bubble size for each group size.
const groupAvatars: Record<string, { avatar: string; px: number }> = {"sm":{"avatar":"xs","px":24},"md":{"avatar":"sm","px":32},"lg":{"avatar":"md","px":40}};

export interface AvatarGroupProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof avatarGroupVariants> {
  /** Show this many avatars, then a +N bubble. */
  max?: number;
  /** Text of the bubble when you count the rest yourself, for example "+5". */
  count?: React.ReactNode;
}

const AvatarGroup = React.forwardRef<HTMLDivElement, AvatarGroupProps>(
  ({ className, size, max, count, children, ...props }, ref) => {
    const all = React.Children.toArray(children);
    const shown = max ? all.slice(0, max) : all;
    const rest = all.length - shown.length;
    const dims = groupAvatars[size ?? "md"];
    return (
      <div data-slot="avatar-group" data-kind="chip" ref={ref} role="group" className={cn(avatarGroupVariants({ size }), className)} {...props}>
        {shown.map((child) => (React.isValidElement(child) ? React.cloneElement(child as React.ReactElement<any>, { size: dims.avatar }) : child))}
        {rest > 0 || count != null ? (
          <span className="inline-flex shrink-0 items-center justify-center rounded-full ring-2 bg-muted text-fg-secondary ring-surface" style={{ width: dims.px, height: dims.px }}>
            {count ?? "+" + rest}
          </span>
        ) : null}
      </div>
    );
  },
);
AvatarGroup.displayName = "AvatarGroup";

export { AvatarGroup, avatarGroupVariants };
